import{_ as d,o as r,c as e,a6 as a}from"./chunks/framework.B_q3ZJNF.js";const p=JSON.parse('{"title":"K线形态速查表","description":"","frontmatter":{"title":"K线形态速查表"},"headers":[],"relativePath":"a-share-investing-course/kline-patterns-cheatsheet.md","filePath":"a-share-investing-course/docs/kline-patterns-cheatsheet.md"}'),h={name:"a-share-investing-course/kline-patterns-cheatsheet.md"};function l(s,t,n,o,i,m){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="k线形态速查表" tabindex="-1">K线形态速查表 <a class="header-anchor" href="#k线形态速查表" aria-label="Permalink to &quot;K线形态速查表&quot;">​</a></h1><p>这张表收录本课程教过的全部 K 线形态：第 5、6 章的单根，第 7 章的双根，第 8 章的三根以上，第 15 章的大型反转结构与缺口。速查表是记忆锚，不是教材——每行只给最短数值判据、一句盘面剧本、一条条件句式与失效条件；判据的来龙去脉、跟算样本与「为什么是这个数」都在各章正文，<strong>判据与剧本一律以章节正文为准</strong>。应对句全部是条件句：出现 X 且满足 Y 时，常见的应对是 Z，失效条件是 W——没有失效条件的建议等于没有建议。</p><p>为了表格紧凑，本课程反复用到的三把尺先约定如下：</p><ul><li><strong>实体占比</strong> = 实体 ÷ 全天振幅（第 3 章 <code>candleAnatomy</code> 的读数），下表判据里的百分比多半用它。</li><li><strong>背景跌／背景涨</strong>：形态之前 5 根（<code>lookback=5</code>）收盘累计跌幅／涨幅 ≥ 5%（<code>threshold=0.05</code>）；涨跌都在 5% 以内记横盘，横盘一律不命名。背景只用形态之前的数据，拒绝未来函数。</li><li><strong>参照尺</strong>：形态之前 5 根 K 线的平均振幅（第 6 章 <code>avgRange</code>）——「长」与「缩」都不在 K 线自己身上，在与近邻的比较里。</li></ul><h2 id="单根·影线族-第-5-章" tabindex="-1">单根·影线族（第 5 章） <a class="header-anchor" href="#单根·影线族-第-5-章" aria-label="Permalink to &quot;单根·影线族（第 5 章）&quot;">​</a></h2><p>判据只读解剖器量出的数字，不读像素长相；锤子／上吊、倒锤子／射击之星是同一形状的两个名字，由背景决定归属——形状 × 位置 = 含义。</p><table tabindex="0"><thead><tr><th>形态</th><th>构成（数值判据）</th><th>盘面含义</th><th>常见应对（条件句）</th><th>失效条件</th><th>详见</th></tr></thead><tbody><tr><td>大阳线</td><td>阳线且实体占比 ≥ 0.7；不看背景</td><td>一方从开盘压到收盘的全场大胜——这一天从头到尾归多方控盘</td><td>出现大阳线、且它收在事先画好的压力区之上、成交量同步放大时，把「多方当日控盘」记为一条事实，再等回踩考虑介入，不追实体顶端</td><td>次日收盘跌回这根大阳线实体的一半以下，控盘判断作废</td><td><a href="./05-single-patterns-wicks.html">第 5 章</a></td></tr><tr><td>大阴线</td><td>阴线且实体占比 ≥ 0.7；不看背景</td><td>空头从开盘杀到收盘，多头连一次像样的反攻都没组织起来——当日空头控盘</td><td>出现大阴线时，把「当日空头控盘」记为一条事实；跌破大阴线最低价的后续走弱才算确认</td><td>镜像大阳线：次日收盘涨回这根大阴线实体的一半以上，控盘判断作废</td><td><a href="./05-single-patterns-wicks.html">第 5 章</a></td></tr><tr><td>光头光脚</td><td>非十字，上下影线各不超过振幅的 5%；可与「大阳／大阴」同时命中，名字不互斥</td><td>一边倒的极端版：盘内连一次值得记录的反扑都没发生</td><td>出现光头光脚大阳线且当日放量、且次日不回补实体时，顺着控盘方向等待回踩机会</td><td>次日低开吞掉大半实体——所谓全天控盘只是单日情绪</td><td><a href="./05-single-patterns-wicks.html">第 5 章</a></td></tr><tr><td>锤子线</td><td>下影 ≥ 2×实体，上影 ≤ 实体，实体占比 &gt; 5%；背景：跌</td><td>空头深砸、收盘收回——长下影只证明「这个价位今天有人愿意要」，不保证见底</td><td>出现在不少于 5% 的下跌之后、且次日收盘没有跌破锤子线最低价时，把「下方出现承接」记为一条线索，等确认信号再动手，不当天就买</td><td>次日收盘跌破锤子线最低价，承接判断作废</td><td><a href="./05-single-patterns-wicks.html">第 5 章</a></td></tr><tr><td>上吊线</td><td>同锤子线形状（下影 ≥ 2×实体、上影 ≤ 实体、实体占比 &gt; 5%）；背景：涨</td><td>高位第一次出现急卖——即便尾盘接了回来，「有人开始在这个位置大笔出货」本身就是新信息</td><td>出现在不少于 5% 的上涨之后、且次日收盘跌进上吊线实体之内时，收紧止盈、不再加仓</td><td>次日放量收阳创出新高，警示作废</td><td><a href="./05-single-patterns-wicks.html">第 5 章</a></td></tr><tr><td>射击之星</td><td>上影 ≥ 2×实体，下影 ≤ 实体，实体占比 &gt; 5%；背景：涨</td><td>多头冲高被全额打回——上方抛压从猜测变成了被实测过的事实</td><td>出现在不少于 5% 的上涨之后、且次日收盘收在射击之星实体之下时，把「上方抛压已实测」记入证据链，停止追加、收紧止盈</td><td>次日放量收阳、收复整条上影，测试结论作废</td><td><a href="./05-single-patterns-wicks.html">第 5 章</a></td></tr><tr><td>倒锤子</td><td>同射击之星形状（上影 ≥ 2×实体、下影 ≤ 实体、实体占比 &gt; 5%）；背景：跌</td><td>跌中多头第一次认真上探——空方已压不出新低，卖压不再是无限子弹</td><td>出现在不少于 5% 的下跌之后、且次日收阳高于倒锤子实体时，把它当作「卖压衰减」的候选线索，等第三日不创新低再升级为线索</td><td>次日收阴且跌破倒锤子最低价</td><td><a href="./05-single-patterns-wicks.html">第 5 章</a></td></tr></tbody></table><h2 id="单根·十字族-第-6-章" tabindex="-1">单根·十字族（第 6 章） <a class="header-anchor" href="#单根·十字族-第-6-章" aria-label="Permalink to &quot;单根·十字族（第 6 章）&quot;">​</a></h2><p>家族地盘 = 实体占比 ≤ 5%，与影线族（&gt; 5%）互补不留缝。判定次序：一字 → 贴边（蜻蜓／墓碑）→ 大小（长腿／纺锤）→ 普通十字兜底——形状优先于大小。犹豫程度：打盹（纺锤）＜ 打平（普通、蜻蜓、墓碑）＜ 撕裂（长腿），一字线不在刻度上。</p><table tabindex="0"><thead><tr><th>形态</th><th>构成（数值判据）</th><th>盘面含义</th><th>常见应对（条件句）</th><th>失效条件</th><th>详见</th></tr></thead><tbody><tr><td>普通十字星</td><td>实体占比 ≤ 5%，且非一字、非贴边、非长腿、非纺锤——家族兜底类；犹豫程度「打平」</td><td>全天攻防互相抵消、净战果归零的平局——记分牌只有上半场，方向写在次日</td><td>出现于一段已有趋势之中时，把仓位和止损原样留到明天——这根 K 线不构成任何新动作的理由</td><td>次日收出实体饱满的方向 K 线，观望状态结束，按新证据重新评估</td><td><a href="./06-single-patterns-doji.html">第 6 章</a></td></tr><tr><td>长腿十字</td><td>实体占比 ≤ 5%，振幅 ≥ 1.2×参照尺，且上下影各占振幅 ≥ 30%；犹豫程度「撕裂」</td><td>两边各被推翻一次——分歧大到双方都亮过底牌，还是没分出胜负</td><td>出现于此前不少于 5% 的单边行情之后时，只减不加，防守位收到长腿十字的中心价附近——不站在任何一边</td><td>次日收盘越过长腿十字的最高价或最低价，分歧判读作废，按突破方向重估</td><td><a href="./06-single-patterns-doji.html">第 6 章</a></td></tr><tr><td>蜻蜓线</td><td>实体占比 ≤ 5%，上影 ≤ 振幅的 5%，下影 ≥ 振幅的 80%；犹豫程度「打平」</td><td>全天砸下去又被全额买回——下方那个价位今天被真实地测试过，是承接的实弹记录、不是承诺</td><td>出现在不少于 5% 的下跌之后、且次日收盘高于蜻蜓线最高价时，把「下方有承接」记为一条线索，等回踩再考虑介入，不当天追</td><td>次日收盘跌破蜻蜓线最低价，承接判读作废</td><td><a href="./06-single-patterns-doji.html">第 6 章</a></td></tr><tr><td>墓碑线</td><td>实体占比 ≤ 5%，下影 ≤ 振幅的 5%，上影 ≥ 振幅的 80%；犹豫程度「打平」</td><td>冲高的买盘全军覆没——上方那个价位今天被真实地测试过，抛压把冲锋全额打了回来</td><td>出现在不少于 5% 的上涨之后、且次日收盘收在墓碑线的开收盘价之下时，收紧止盈、停止追加</td><td>次日放量收阳、收复整条上影，抛压判读作废</td><td><a href="./06-single-patterns-doji.html">第 6 章</a></td></tr><tr><td>纺锤线</td><td>实体占比 ≤ 5%，振幅 ≤ 0.5×参照尺；犹豫程度「打盹」</td><td>不是打成平局，是压根没怎么打——买卖双方都无意恋战，市场在打盹，常是趋势中途歇脚</td><td>什么都不做——它不含方向信息，硬读就是赌</td><td>次日走出放量的方向 K 线，「无信息」状态结束，按新 K 线评估</td><td><a href="./06-single-patterns-doji.html">第 6 章</a></td></tr><tr><td>一字线（跌停语境）</td><td>开 = 高 = 低 = 收（振幅为 0），且价格恰等于昨收 ×（1−10%）四舍五入到分（主板口径 <code>limitRatio=0.1</code>，可传参）；犹豫程度「锁死」</td><td>想卖的排队卖不掉——价格锁死，战斗没有发生，它不是犹豫的极致，是犹豫刻度的出局者</td><td>持仓出现一字跌停时，按跌停价挂单排队，并接受可能卖不掉的现实；同时回头检讨仓位——单笔仓位应压到「连续三个一字跌停也伤不了根本」</td><td>盘中封单打开、成交放大，锁死解除，按正常盘面重新评估</td><td><a href="./06-single-patterns-doji.html">第 6 章</a></td></tr><tr><td>一字线（涨停语境）</td><td>四价合一，且价格恰等于昨收 ×（1+10%）四舍五入到分（主板口径）</td><td>想买的排队买不到——追涨停排队不是犹豫，是在赌次日惯性</td><td>排队追买的单子同样可能全天不成交——不把它当形态信号读，只当作赌惯性的排队</td><td>盘中封单打开、成交放大，锁死解除，按正常盘面重新评估</td><td><a href="./06-single-patterns-doji.html">第 6 章</a></td></tr></tbody></table><h2 id="双根-第-7-章" tabindex="-1">双根（第 7 章） <a class="header-anchor" href="#双根-第-7-章" aria-label="Permalink to &quot;双根（第 7 章）&quot;">​</a></h2><p>双根读「今天怎么回应昨天」：扩张（吞没）、攻进腹地（乌云盖顶／刺透）、收缩（孕线）、重复测试（平顶／平底）。完成日是第二根；背景沿用第 5 章窗口，横盘不命名。<strong>中点 =（昨开 + 昨收）÷ 2</strong>——不是几何装饰，是多空重新开战的战线。</p><table tabindex="0"><thead><tr><th>形态</th><th>构成（数值判据）</th><th>盘面含义</th><th>常见应对（条件句）</th><th>失效条件</th><th>详见</th></tr></thead><tbody><tr><td>看涨吞没</td><td>背景：跌；昨天实体占比 &gt; 5%；今天阳线实体顶 ≥ 昨天实体顶、底 ≤ 昨天实体底，且至少一头严格越过</td><td>买方连本带利收回昨天卖方的战果——今天的回应是扩张</td><td>出现在不少于 5% 的下跌之后、且当天量能明显放大时，把「买方接管」记为一条线索，等次日回踩不创新低再考虑介入</td><td>次日收盘跌回今天阳线实体的中点之下，接管判读作废</td><td><a href="./07-multi-patterns-two.html">第 7 章</a></td></tr><tr><td>看跌吞没</td><td>背景：涨；昨天实体占比 &gt; 5%；今天阴线实体两头包住昨天实体且至少一头严格越过</td><td>卖方把昨天买方的战果连本带利圈走——扩张的镜像</td><td>上涨后放量阴线包住昨天阳线时，收紧止盈、停止追加</td><td>次日收盘收复今天阴线实体的中点</td><td><a href="./07-multi-patterns-two.html">第 7 章</a></td></tr><tr><td>乌云盖顶</td><td>背景：涨；昨天阳线，今天高开（今开 &gt; 昨收）收阴，今收 &lt; 昨天实体中点，且今收 &gt; 昨开（仍收在昨天实体之内；恰好压在中点上不判）</td><td>高开是乐观的尾巴，收不过中点是反转的正文——昨天胜方失守半壁战线</td><td>出现乌云盖顶、且次日收盘收在乌云阴线最低价之下时，减仓防守——反转可以等确认，防守不必等</td><td>次日放量收阳、收复昨天阳线实体的中点，乌云判读作废</td><td><a href="./07-multi-patterns-two.html">第 7 章</a></td></tr><tr><td>刺透形态</td><td>背景：跌；昨天阴线，今天低开（今开 &lt; 昨收）收阳，今收 &gt; 昨天实体中点，且今收 &lt; 昨开（收在昨天实体之内）</td><td>恐慌盘在低位交出的筹码，被正面买了回去——反击方打回昨天战场过半</td><td>出现刺透、且次日收盘高于刺透阳线最高价时，把「下方有承接」记为线索、等回踩再考虑介入，不当天追</td><td>次日收盘跌破昨天阴线的最低价，反击判读作废</td><td><a href="./07-multi-patterns-two.html">第 7 章</a></td></tr><tr><td>看涨孕线</td><td>背景：跌；昨天大实体（实体占比 ≥ 0.7）；今天小阳实体两头严格缩在昨天实体之内，实体 ≤ 昨天实体的 1/3</td><td>卖压没有延续——昨天胜方没乘胜追击，买方小规模还手且全身而退，「跌不动了」的第一份证据</td><td>出现在下跌之后时，把「卖压收缩」记为线索、观察次日</td><td>次日收盘跌破昨天大阴线的最低价，刹车判读作废</td><td><a href="./07-multi-patterns-two.html">第 7 章</a></td></tr><tr><td>看跌孕线</td><td>背景：涨；昨天大阳（实体占比 ≥ 0.7）；今天小阴实体严格缩在其内，实体 ≤ 昨天实体的 1/3</td><td>涨势的攻势突然踩了刹车——扩张的对偶是收缩</td><td>上涨后小阴缩进大阳时，收紧止盈</td><td>次日收盘越过昨天大阳线的最高价</td><td><a href="./07-multi-patterns-two.html">第 7 章</a></td></tr><tr><td>十字孕线</td><td>昨天大实体（实体占比 ≥ 0.7）；今天十字（实体占比 ≤ 5%）严格缩在其内；倾向来自背景：跌后偏多、涨后偏空</td><td>犹豫到极致，常是变盘前夜——它是待确认的倾向，不是信号</td><td>出现时只观察不动手；次日收出实体饱满的方向 K 线并越过十字的高点或低点，倾向才升级为线索</td><td>次日反向越过十字的高点或低点，倾向作废</td><td><a href="./07-multi-patterns-two.html">第 7 章</a></td></tr><tr><td>平顶</td><td>背景：涨；两根高点之差 ≤ 0.1×参照尺（形态之前 5 根平均振幅的一成）</td><td>同一价位两次把买方挡在外面——上面有人守的初步证据</td><td>出现在上涨之后、且两根中第二根收阴时，把「上方有守军」记为线索、停止追加</td><td>次日收盘越过两根的共同高点，守军判读作废，按突破重估——也要当心专门收割追单的假突破</td><td><a href="./07-multi-patterns-two.html">第 7 章</a></td></tr><tr><td>平底</td><td>背景：跌；两根低点之差 ≤ 0.1×参照尺</td><td>同一价位两次把价格接了回来——下面有人接的初步证据</td><td>下跌后两根低点几乎相同时，把「下方有承接」记为一条线索</td><td>次日收盘跌破共同低点</td><td><a href="./07-multi-patterns-two.html">第 7 章</a></td></tr></tbody></table><h2 id="三根以上-第-8-章" tabindex="-1">三根以上（第 8 章） <a class="header-anchor" href="#三根以上-第-8-章" aria-label="Permalink to &quot;三根以上（第 8 章）&quot;">​</a></h2><p>背景门分两档：反转（晨星／暮星）与中继（三法）沿用第 5 章窗口——没有趋势就没有可反转或可中继的对象；推进（三兵／三鸦／受阻）不设门——三根同向推进的 K 线就是自己的语境。完成日是最后一根。</p><table tabindex="0"><thead><tr><th>形态</th><th>构成（数值判据）</th><th>盘面含义</th><th>常见应对（条件句）</th><th>失效条件</th><th>详见</th></tr></thead><tbody><tr><td>早晨之星</td><td>背景：跌；第一根大阴（实体占比 ≥ 0.7）；第二根实体 ≤ 第一根实体的 1/3 且实体顶低于第一根实体底（悬空）；第三根阳线收盘 &gt; 第一根实体中点（严格越过，压线不判）；量能线：第三根量 ≥ 前两根较大者 × 1.2，不足降级「未确认」</td><td>三幕反转剧：卖压枯竭、犹豫、买方接管——把「次日确认」装进了形态里</td><td>出现在不少于 5% 的下跌之后、收复与量能双双过线时，把「底部接管」记为一条线索，等回踩星线区域不创新低再考虑介入，不当天追；未确认的记为线索再等一天，次日量能补上且收盘站稳中点之上则升级</td><td>次日收盘跌回第一根阴线实体的中点之下，接管判读作废；未确认版：次日收盘跌回星线最低价之下</td><td><a href="./08-multi-patterns-three.html">第 8 章</a></td></tr><tr><td>黄昏之星</td><td>背景：涨；第一根大阳（实体占比 ≥ 0.7）；星线实体 ≤ 第一根实体的 1/3 且实体底高于第一根实体顶；第三根阴线收盘 &lt; 第一根实体中点；量能线同晨星（1.2 倍，不足降级）</td><td>晨星照镜子——涨势熄火的三幕剧</td><td>出现在一段上涨之后、收复与量能双双过线时，收紧止盈、停止追加，把「涨势熄火」记为线索；量能不足的同样降级为未确认，等一天再定</td><td>次日收盘收复第一根阳线实体的中点，熄火判读作废</td><td><a href="./08-multi-patterns-three.html">第 8 章</a></td></tr><tr><td>红三兵</td><td>三根阳线，每根实体占比 ≥ 0.5；每根开盘嵌在前根实体内（不跳空抢跑）；收盘逐根抬高；不设背景门</td><td>趋势自己的缩影——每天小步高开、稳稳收高的健康推进</td><td>出现在低位或涨势初期、三根量能逐根温和放大时，把「推进健康」记为线索、顺势持有或等回踩介入</td><td>次日收盘跌破第三根兵的开盘价，推进判读作废</td><td><a href="./08-multi-patterns-three.html">第 8 章</a></td></tr><tr><td>红三兵受阻</td><td>前三根是红三兵；第四根开盘 ≥ 第三根收盘（姿态还在冲），且实体占自身振幅 ≤ 0.3 或上影 ≥ 2×实体</td><td>姿态与战果脱节——还想冲，冲不动了；墙不是反转，是阻力第一次现形</td><td>受阻出现、且次日收盘跌破第四根的低点时，暂停追加、把止损上移到第三根兵的收盘</td><td>次日放量收阳越过第四根的高点，撞墙判读作废，按推进重启对待</td><td><a href="./08-multi-patterns-three.html">第 8 章</a></td></tr><tr><td>黑三鸦</td><td>三根阴线，每根实体占比 ≥ 0.5；开盘逐根嵌在前根实体内；收盘逐根压低；不设背景门</td><td>红三兵的镜像——空头稳步推进，鸦群推进配的是放量</td><td>出现在高位或跌势中时，回避抄底</td><td>次日收盘越过第三根鸦的开盘价</td><td><a href="./08-multi-patterns-three.html">第 8 章</a></td></tr><tr><td>上升三法</td><td>背景：涨；第一根大阳（实体占比 ≥ 0.7）立框；中间三根高低点均不越第一根的高低点、实体 ≤ 第一根实体的 1/3、收盘全部低于第一根收盘；第五根大阳（≥ 0.7）收盘 &gt; 第一根收盘</td><td>五幕中继剧：推进、歇脚、再推进——回撤被全额收复，歇脚不折返</td><td>完成、且次日收盘守住第五根实体中点之上时，把「回撤健康」记为线索、继续持有原趋势仓位</td><td>次日收盘跌破第一根大阳的开盘价，歇脚判读作废、按折返重估</td><td><a href="./08-multi-patterns-three.html">第 8 章</a></td></tr><tr><td>下降三法</td><td>背景：跌；第一根大阴（实体占比 ≥ 0.7）立框；中间三根缩在框内、实体 ≤ 第一根实体的 1/3、收盘全部高于第一根收盘；第五根大阴（≥ 0.7）收盘 &lt; 第一根收盘</td><td>下跌中继——反弹缩在框内消化，第五根杀回新低</td><td>反弹缩在框内、第五根杀回新低时，回避接飞刀</td><td>次日收盘越过第一根大阴的开盘价</td><td><a href="./08-multi-patterns-three.html">第 8 章</a></td></tr></tbody></table><h2 id="大型结构与缺口-第-15-章" tabindex="-1">大型结构与缺口（第 15 章） <a class="header-anchor" href="#大型结构与缺口-第-15-章" aria-label="Permalink to &quot;大型结构与缺口（第 15 章）&quot;">​</a></h2><p>结构口径出自 <code>detectStructures</code>：枢轴取左右各 3 根（k=3）的严格局部极值；「同水平」容差 tol 默认 = 全序列平均振幅的一半（正文图上显式取 0.25 元）；破位只认收盘，盘中影线刺破不算；量度目标 = 结构高度从颈线投影，是参考区不是承诺。缺口三分类是第 15 章的教学口径（识别不进实验场模块），分诊只问两件事：多快回补、量放多大。</p><table tabindex="0"><thead><tr><th>形态</th><th>构成（数值判据）</th><th>盘面含义</th><th>常见应对（条件句）</th><th>失效条件</th><th>详见</th></tr></thead><tbody><tr><td>头肩顶</td><td>枢轴五连「高、低、高、低、高」：两肩价差 ≤ tol，头 ≥ 较高肩 + tol，两谷价差 ≤ tol，肩与颈线拉开 ≥ tol；颈线 = 两谷枢轴价均值；右肩之后第一根收盘 &lt; 颈线结构才成立；量度目标 = 2×颈线 − 头价</td><td>三段情绪的接力：左肩正常回撤、头是最后的冲锋、右肩乏力——买方接力一次比一次弱</td><td>若持有多头仓位且右肩成形，常见的应对是把止盈线挂在颈线下方一点，收盘跌破执行，不等反弹；量度目标抵达之前若出现放量承接，降级预期——它量的是惯性距离，不是承诺的底</td><td>收盘收回颈线上方（假跌破），或右肩上攻超过头高——结构作废，按趋势延续处理</td><td><a href="./15-reversal-structures.html">第 15 章</a></td></tr><tr><td>双顶</td><td>枢轴三连「峰、谷、峰」：两峰价差 ≤ tol，中间谷深度（较低峰 − 谷价）≥ tol；颈线取中间谷枢轴价；第二峰之后第一根收盘 &lt; 颈线才成立；量度目标 = 2×颈线 − 两峰均价</td><td>同一个价位两次证明有人守——M 形顶部，头肩顶的退化版（头没长出来）</td><td>条件句镜像双底（同章）：走完 M 形、收盘跌破中间谷（颈线）时，把中间谷下方设为参照、以收盘收回颈线为失效</td><td>收盘收回颈线上方（假跌破口径与头肩顶一字不差），或收盘涨回峰顶之上，结构作废</td><td><a href="./15-reversal-structures.html">第 15 章</a></td></tr><tr><td>双底</td><td>枢轴三连「谷、峰、谷」：两谷价差 ≤ tol，中间峰高度（峰价 − 较高谷）≥ tol；颈线取中间峰枢轴价；第二谷之后第一根收盘 &gt; 颈线才成立；量度目标 = 2×颈线 − 两谷均价</td><td>两次砸坑都砸不穿——同一个价位两次证明下方有人接，W 形底部</td><td>若观察的标的走完 W 形、收盘涨过中间峰，常见的应对是把中间峰上方设为参照、以跌回颈线为失效</td><td>收盘跌回谷底之下，结构作废</td><td><a href="./15-reversal-structures.html">第 15 章</a></td></tr><tr><td>普通缺口</td><td>缺口 = 今日最低 &gt; 昨日最高的真空区（向下镜像：今日最高 &lt; 昨日最低）；震荡区里的零星跳空，两三天内日内波动把真空走完，无接力资金</td><td>隔夜小消息的零星跳空——不预测方向，也基本不含信息</td><td>不据此动作——把它从证据链里划掉，不当信号读</td><td>若三天不回补且量能持续放大，重新分诊为突破缺口（分诊只问回补快慢与量能大小）</td><td><a href="./15-reversal-structures.html">第 15 章</a></td></tr><tr><td>突破缺口</td><td>跳空脱离成本区（开盘落在横盘区上沿之外）+ 放量（如当日量为前五日均量的 3.3 倍）+ 此后久久不回补</td><td>市场用真金白银投票：这个区域上方重新定价——「缺口不补，强势依旧」</td><td>若横盘区上沿出现放量跳空、三天不回补，常见的应对是不追第一根、等回踩缺口上沿不破再参与</td><td>收盘跌回缺口之内即失效</td><td><a href="./15-reversal-structures.html">第 15 章</a></td></tr><tr><td>衰竭缺口</td><td>急涨末端的最后一跳（如连板后的高开跳空），量能放不动、封单越来越薄；随后某天巨量开板、价格跌回缺口反转向下</td><td>最后一跳是燃料烧尽前的火苗——想卖的等更高价、想买的不敢再追</td><td>若持仓且急涨末端出现向上跳空、量能不再放大，常见的应对是把止损收到缺口下沿</td><td>缺口三天不回补且量能持续放大，按突破缺口对待，止损位相应上移</td><td><a href="./15-reversal-structures.html">第 15 章</a></td></tr></tbody></table><hr><p>提醒一句：本表是速查记忆锚，附录速查表与实现的一致性由管线对账；表中全部阈值（0.7、5%、两倍、1/3、0.5、0.3、1.2 倍、一成容差等）均为本课程的操作化选择，详见各章「简化之处」与<a href="./divergence-list.html">差异清单</a>。</p><p>最后一句比所有判据都重要：<strong>投资有风险，入市需谨慎</strong>。本表全部「常见应对」都是教学示例（条件句），不构成投资建议；形态是概率线索，不是信号，历史规律不保证未来。</p>',22)])])}const u=d(h,[["render",l]]);export{p as __pageData,u as default};
